  // parameters: this compiler accepts a CONSTANT index into a real array
  // parameter but rejects a variable one ("Variable index into array
  // parameter requires integral elements"), and every use here is
  // variable-indexed.
  //--------------------------------------------------------------------
  localparam int GOLD_N = 41;

